0,690,'_post_one_page_show_title','field_64f8759c6a2a2'),(28651,690,'post_table_of_contents','0'),(28652,690,'_post_table_of_contents','field_68651a9b0c6ac'),(28653,690,'lang','auto'),(28654,690,'_lang','field_636e42408367e'),(28655,717,'url','https://filbornaarena.se/simborgarmarkesdagen#Simborgarm%C3%A4rkesdagen'),(28656,717,'_url','field_69c4f5e8b7e72'),(28657,717,'[field_68d28f0c845d0','a:1:{i:0;a:1:{s:19:\"field_68d28f0c8845b\";s:2:\"no\";}}'),(28658,717,'_[field_68d28f0c845d0',''),(28659,717,'occasions_0_date','20260523'),(28660,717,'_occasions_0_date','field_68d28f0c89b49'),(28661,717,'occasions_0_startTime','10:00'),(28662,717,'_occasions_0_startTime','field_68d28f0c8a391'),(28663,717,'occasions_0_endTime','15:00'),(28664,717,'_occasions_0_endTime','field_68d28f0c8a6ff'),(28665,717,'occasions_0_url','https://filbornaarena.se/simborgarmarkesdagen#Simborgarm%C3%A4rkesdagen'),(28666,717,'_occasions_0_url','field_68d28f0c8abbe'),(28667,717,'occasions_0_description','<p data-start=\"157\" data-end=\"317\">Hur simkunnig är du egentligen?&nbsp;</p><p data-start=\"157\" data-end=\"317\">D<span style=\"font-size: 15.2px;\">en 23 maj bjuder Helsingborgs Simsällskap och Filborna Arena in till Simborgarmärkesdagen – en dag där du får testa din simkunnighet på riktigt.</span></p>\r\n<p data-start=\"319\" data-end=\"499\">Under dagen har du möjlighet att ta simborgarmärket genom att simma 200 meter sammanhängande. En rolig utmaning för dig som är simkunnig och vill testa din uthållighet i vattnet.</p>\r\n<p data-start=\"501\" data-end=\"664\">Utöver simningen bjuder vi på en härlig dag med mingel, tävlingar och aktiviteter utanför entrén. Perfekt att göra tillsammans med familj, vänner eller kollegor.</p>\r\n<p data-start=\"666\" data-end=\"754\"><strong data-start=\"666\" data-end=\"676\"><br></strong></p><p data-start=\"666\" data-end=\"754\"><strong data-start=\"666\" data-end=\"676\">Datum:</strong> 23 maj 2026<br data-start=\"688\" data-end=\"691\">\r\n<strong data-start=\"691\" data-end=\"699\">Tid:</strong> 10:00–15:00<br data-start=\"711\" data-end=\"714\">\r\n<strong data-start=\"714\" data-end=\"724\">Plats:</strong> Filborna Arena, Helsingborg</p>\r\n<p data-start=\"756\" data-end=\"802\"><br></p><p data-start=\"756\" data-end=\"802\">Barn under 12 år måste delta tillsammans med en simmande vuxen.</p>\r\n<p data-start=\"804\" data-end=\"869\">Alla som klarar simningen får simborgarmärket och en goodiebag.</p>\r\n<p data-start=\"871\" data-end=\"911\">Boka din tid i förväg via vår hemsida.</p>\r\n<p data-start=\"913\" data-end=\"1009\">Välkommen till en dag där vi sätter fokus på en av våra viktigaste livskunskaper – simkunnighet.</p>'),(28668,717,'_occasions_0_description','field_68dd084d90dc7'),(28669,717,'occasions','1'),(28670,717,'_occasions','field_68d28f0c845d0'),(28671,717,'attendancemode','offline'),(28672,717,'_attendancemode','field_696e24e5660ed'),(28673,717,'locationName','Filborna Arena'),(28674,717,'_locationName','field_696e24e566ca3'),(28675,717,'locationAddress','a:13:{s:7:\"address\";s:96:\"105, Filbornavägen, Fredriksdal, Helsingborg, Helsingborgs kommun, Skåne län, 256 61, Sverige\";s:3:\"lat\";d:56.0560544;s:3:\"lng\";d:12.7320108;s:4:\"zoom\";i:15;s:8:\"place_id\";N;s:13:\"street_number\";s:3:\"105\";s:11:\"street_name\";s:14:\"Filbornavägen\";s:4:\"city\";s:0:\"\";s:5:\"state\";s:11:\"Skåne län\";s:9:\"post_code\";s:6:\"256 61\";s:7:\"country\";s:7:\"Sverige\";s:13:\"country_short\";s:2:\"SE\";s:16:\"address_locality\";s:19:\"Helsingborgs kommun\";}'),(28676,717,'_locationAddress','field_696e24e567083'),(28677,717,'pricesList_0_priceLabel','Standardbiljett'),(28678,717,'_pricesList_0_priceLabel','field_6970c90e72676'),(28679,717,'pricesList_0_price','65'),(28680,717,'_pricesList_0_price','field_6970c90e72a49'),(28681,717,'pricesList','1'),(28682,717,'_pricesList','field_6970c90e7034a'),(28683,717,'audience','a:6:{i:0;s:2:\"45\";i:1;s:2:\"84\";i:2;s:2:\"38\";i:3;s:2:\"85\";i:4;s:2:\"42\";i:5;s:2:\"83