INSERT INTO `apiv2_5_posts` VALUES (1,1,'2023-12-08 07:34:36','2023-12-08 06:34:36','Välkommen till <a href=\"https://api.municipio.tech/\">Helsingborgs stads api:er</a>. Detta är ditt första inlägg. Du kan redigera det eller ta bort det. Sedan är det bara att börja skriva!','Hej världen!','','publish','open','open','','hej-varlden','','','2023-12-08 07:34:36','2023-12-08 06:34:36','',0,'https://event.api.municipio.tech/?p=1',0,'post','',1),(32,12,'2024-05-07 14:44:19','2024-05-07 12:44:19','','hbg_liggande_tegel','','inherit','open','closed','','hbg_liggande_tegel','','','2024-05-07 14:44:19','2024-05-07 12:44:19','',0,'https://event.helsingborg.io/wp-content/uploads/sites/5/2024/05/hbg_liggande_tegel.svg',0,'attachment','image/svg+xml',0),(33,12,'2024-05-07 14:44:19','2024-05-07 12:44:19','','helsingborg_logo_a1_rgb_13','','inherit','open','closed','','helsingborg_logo_a1_rgb_13','','','2024-05-07 14:44:19','2024-05-07 12:44:19','',0,'https://event.helsingborg.io/wp-content/uploads/sites/5/2024/05/helsingborg_logo_a1_rgb_13.svg',0,'attachment','image/svg+xml',0),(34,12,'2024-05-07 14:44:21','2024-05-07 12:44:21','','emblem-hbg','','inherit','open','closed','','emblem-hbg','','','2024-05-07 14:44:21','2024-05-07 12:44:21','',0,'https://event.helsingborg.io/wp-content/uploads/sites/5/2024/05/emblem-hbg.svg',0,'attachment','image/svg+xml',0),(36,12,'2024-05-07 14:44:27','2024-05-07 12:44:27','header, footer {\n	display: none !important;\n}\n\n.t-block-container {\n	box-shadow: inset 0 0 2000px;\n	padding: 32px 16px !important;\n  min-height: 100vh;\n  display: flex;\n	background-attachment: fixed;\n}\n\n.adminlink {\n	    text-align: center;\n    align-self: center;\n    margin: 16px auto;\n}\n\n.adminlink a {\n	color: #fff !important;\n}','municipio','','publish','closed','closed','','municipio','','','2026-01-20 16:10:31','2026-01-20 15:10:31','',0,'https://event.helsingborg.io/2024/05/07/municipio/',0,'custom_css','',0),(37,12,'2024-05-07 14:44:27','2024-05-07 12: